mapper.select:
SELECT eq.equipe_id,
eq.administrateur_cip,
eq.nom_equipe
FROM app.equipe as eq

    JOIN app.est_dans as membre ON membre.equipe_id = eq.equipe_id


    
        AND eq.equipe_id = #{equipeId}
    
    
        AND eq.administrateur_cip = #{administrateur}
    
    
        AND eq.nom_equipe = #{nomEquipe}
    
    
        AND membre.cip = ANY(#{usersCip, jdbcType=OTHER, typeHandler=org.apache.ibatis.type.ArrayTypeHandler})

SELECT equipe_id, administrateur_cip, nom_equipe
FROM app.equipe
WHERE equipe_id = #{equipeId}
